descriptor.controllerScript:
self.onInit = function() {
    self.ctx.$scope.zones = [];

    self.ctx.$scope.select = function(actionName, item){
        self.ctx.$scope.zones.forEach(x=>x.isSelected = false);

        if(item){
            item.isSelected = true;
        }

        let actionEventDescriptors = self.ctx.$scope.ctx.actionsApi.getActionDescriptors('elementClick');
        let actionEvent;

        if (actionEventDescriptors.length) {
            actionEventDescriptors.forEach(action=>{
                if(action.name == actionName){
                    actionEvent = action;
                }
            })

            setTimeout(() => {
                self.ctx.$scope.ctx.actionsApi.handleWidgetAction(null, actionEvent, item.id, item.name, item.type);	
                self.ctx.detectChanges();
            }, 0);	
            self.ctx.detectChanges();
        }
    }
}

self.onDataUpdated = function() {
    self.ctx.$scope.zones = [];

    self.ctx.datasources.forEach((x,index)=>{
        let zone = {
            id: x.entity.id,
            isSelected: false
        };

        self.ctx.data.forEach(y=>{
            if(y.datasource.entityId == x.entityId){
                if(y.data[0]){
                    zone[y.dataKey.name] = y.data[0][1]
                }
            }
        })
        self.ctx.$scope.zones.push(zone);
    })

    self.ctx.$scope.zones.unshift({
        name: "All zones",
        isSelected: false,
        id: {
            id: self.ctx.currentUser.userId,
            entityType: "USER"
        }
    });

    // console.log(self.ctx.dashboard.isEdit)
    if(self.ctx.$scope.zones.length && !self.ctx.dashboard.isEdit){
        self.ctx.$scope.select('select', self.ctx.$scope.zones[0]);    
    }

    self.ctx.detectChanges();
}

self.actionSources = function() {
    return {
        'elementClick': {
            name: 'On HTML click',
            multiple: true
        }
    };
};

self.onResize = function() {
}

self.onDestroy = function() {
}

